import Foundation

/// Цитата в том виде, в каком её видят экраны. Не зависит от способа хранения.
public struct BookQuote: Identifiable, Hashable, Sendable {
    public let id: UUID
    public let text: String
    public let bookID: UUID
    public let createdAt: Date

    public init(id: UUID, text: String, bookID: UUID, createdAt: Date) {
        self.id = id
        self.text = text
        self.bookID = bookID
        self.createdAt = createdAt
    }
}

public enum QuoteRepositoryError: Error, Equatable {
    case emptyText
}

/// Хранилище цитат. Экраны работают только через этот протокол.
public protocol QuoteRepository: Sendable {
    /// Цитаты книги, новые сверху.
    func quotes(forBook bookID: UUID) async throws -> [BookQuote]
    /// Сохраняет цитату. Пробелы по краям обрезаются; пустой текст — ошибка `.emptyText`.
    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote
    /// Удаляет цитату. Если её уже нет — ничего не делает.
    func deleteQuote(id: BookQuote.ID) async throws
}

/// Общее правило для всех реализаций, чтобы они вели себя одинаково.
public enum QuoteRules {
    public static func validatedText(_ raw: String) throws -> String {
        let text = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { throw QuoteRepositoryError.emptyText }
        return text
    }
}
