import Foundation

/// Хранилище в памяти: для превью и тестов. Ничего не сохраняет между запусками.
public actor InMemoryQuoteRepository: QuoteRepository {
    private var storage: [BookQuote]
    private let now: @Sendable () -> Date

    public init(quotes: [BookQuote] = [], now: @escaping @Sendable () -> Date = { .now }) {
        self.storage = quotes
        self.now = now
    }

    public func quotes(forBook bookID: UUID) -> [BookQuote] {
        storage
            .filter { $0.bookID == bookID }
            .sorted { $0.createdAt > $1.createdAt }
    }

    public func addQuote(text: String, toBook bookID: UUID) throws -> BookQuote {
        let quote = BookQuote(
            id: UUID(),
            text: try QuoteRules.validatedText(text),
            bookID: bookID,
            createdAt: now()
        )
        storage.append(quote)
        return quote
    }

    public func deleteQuote(id: BookQuote.ID) {
        storage.removeAll { $0.id == id }
    }
}
