import Foundation
import SwiftData
import SlumpyCore

/// Реализация на SwiftData. При переходе на GRDB заменяется только этот файл.
public actor SwiftDataQuoteRepository: QuoteRepository, ModelActor {
    public nonisolated let modelContainer: ModelContainer
    public nonisolated let modelExecutor: any ModelExecutor
    private let now: @Sendable () -> Date

    public init(modelContainer: ModelContainer, now: @escaping @Sendable () -> Date = { .now }) {
        self.modelContainer = modelContainer
        self.modelExecutor = DefaultSerialModelExecutor(modelContext: ModelContext(modelContainer))
        self.now = now
    }

    public func quotes(forBook bookID: UUID) throws -> [BookQuote] {
        let descriptor = FetchDescriptor<Quote>(
            predicate: #Predicate { $0.bookID == bookID },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        return try modelContext.fetch(descriptor).map(BookQuote.init)
    }

    public func addQuote(text: String, toBook bookID: UUID) throws -> BookQuote {
        let quote = Quote(
            id: UUID(),
            text: try QuoteRules.validatedText(text),
            bookID: bookID,
            createdAt: now()
        )
        modelContext.insert(quote)
        try saveOrRollback()
        return BookQuote(quote)
    }

    public func deleteQuote(id: BookQuote.ID) throws {
        let quoteID = id
        let descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.id == quoteID })
        let matches = try modelContext.fetch(descriptor)
        guard !matches.isEmpty else { return }
        for quote in matches {
            modelContext.delete(quote)
        }
        try saveOrRollback()
    }

    /// Если запись на диск не удалась, отменяем несохранённые изменения,
    /// чтобы они не всплыли при следующем сохранении.
    private func saveOrRollback() throws {
        do {
            try modelContext.save()
        } catch {
            modelContext.rollback()
            throw error
        }
    }
}

extension BookQuote {
    init(_ quote: Quote) {
        self.init(id: quote.id, text: quote.text, bookID: quote.bookID, createdAt: quote.createdAt)
    }
}
```

### 6. Приложение: модель экрана, экран и запуск

```swift
// BookQuotesModel.swift
import Foundation
import Observation
import SlumpyCore

@MainActor
@Observable
final class BookQuotesModel {
    private(set) var quotes: [BookQuote] = []
    private(set) var isSaving = false
    var errorMessage: String?

    var isShowingError: Bool {
        get { errorMessage != nil }
        set { if !newValue { errorMessage = nil } }
    }

    let bookID: UUID
    private let repository: any QuoteRepository
    private var loadGeneration = 0

    init(bookID: UUID, repository: any QuoteRepository) {
        self.bookID = bookID
        self.repository = repository
    }

    func reload() async {
        loadGeneration += 1
        let generation = loadGeneration
        do {
            let fresh = try await repository.quotes(forBook: bookID)
            // Если за время ожидания начата более новая загрузка, этот результат устарел.
            guard generation == loadGeneration else { return }
            quotes = fresh
        } catch {
            errorMessage = "Не удалось загрузить цитаты."
        }
    }

    /// Возвращает true, если цитата сохранена (тогда экран очищает поле ввода).
    func add(text: String) async -> Bool {
        guard !isSaving else { return false }
        isSaving = true
        defer { isSaving = false }
        do {
            _ = try await repository.addQuote(text: text, toBook: bookID)
        } catch QuoteRepositoryError.emptyText {
            errorMessage = "Цитата пустая."
            return false
        } catch {
            errorMessage = "Не удалось сохранить цитату."
            return false
        }
        await reload()
        return true
    }

    func delete(_ targets: [BookQuote]) async {
        let ids = Set(targets.map(\.id))
        // Сразу убираем строки, чтобы анимация удаления в списке не дёргалась.
        quotes.removeAll { ids.contains($0.id) }
        do {
            for id in ids {
                try await repository.deleteQuote(id: id)
            }
        } catch {
            errorMessage = "Не удалось удалить цитату."
        }
        await reload()
    }
}
```

