// SlumpyStorageTests/QuoteRepositoryContractTests.swift
import Foundation
import SwiftData
import Synchronization
import Testing
import SlumpyCore
import SlumpyStorage

/// Часы для тестов: каждое обращение на секунду позже предыдущего.
final class TestClock: Sendable {
    private let current = Mutex(Date(timeIntervalSince1970: 0))
    func next() -> Date {
        current.withLock { date in
            date += 1
            return date
        }
    }
}

enum RepositoryKind: CaseIterable, Sendable {
    case inMemory, swiftData

    func make(clock: TestClock) throws -> any QuoteRepository {
        switch self {
        case .inMemory:
            return InMemoryQuoteRepository(now: { clock.next() })
        case .swiftData:
            let config = ModelConfiguration(isStoredInMemoryOnly: true)
            let container = try ModelContainer(for: Quote.self, configurations: config)
            return SwiftDataQuoteRepository(modelContainer: container, now: { clock.next() })
        }
    }
}

struct QuoteRepositoryContractTests {
    @Test(arguments: RepositoryKind.allCases)
    func listsOnlyThisBookNewestFirst(kind: RepositoryKind) async throws {
        let repo = try kind.make(clock: TestClock())
        let book = UUID(), otherBook = UUID()
        let first = try await repo.addQuote(text: "Первая", toBook: book)
        _ = try await repo.addQuote(text: "Чужая", toBook: otherBook)
