```swift
import Foundation

/// Цитата так, как её видят экраны. Не зависит от того, где и как она хранится.
struct BookQuote: Identifiable, Hashable, Sendable {
    let id: UUID
    let bookID: UUID
    let text: String
    let createdAt: Date
}

enum QuoteStoreError: Error, Equatable {
    /// Текст пустой или состоит только из пробелов.
    case emptyText
}

/// Хранилище цитат. Экраны работают только с ним и ничего не знают о SwiftData или GRDB.
@MainActor
protocol QuoteStore: AnyObject, Sendable {
    /// Цитаты книги, новые сверху. Сразу присылает текущий список,
    /// затем присылает новый после каждого добавления или удаления цитаты этой книги.
    func quotes(ofBook bookID: UUID) -> AsyncThrowingStream<[BookQuote], any Error>

    /// Убирает пробелы по краям текста. Пустой текст: `QuoteStoreError.emptyText`.
    @discardableResult
    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote

    /// Удаляет цитату. Если её уже нет, ничего не делает.
    func deleteQuote(id quoteID: UUID) async throws
}

/// Правила, общие для всех хранилищ.
extension BookQuote {
    static func normalizedText(_ raw: String) throws -> String {
        let text = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { throw QuoteStoreError.emptyText }
        return text
    }

    static func newestFirst(_ lhs: BookQuote, _ rhs: BookQuote) -> Bool {
        lhs.createdAt > rhs.createdAt
    }
}
