## Файл 2. `QuoteSubscriptions.swift`: рассылка обновлений открытым экранам

```swift
import Foundation

/// Помнит, какие экраны следят за какой книгой, и присылает им свежий список
/// после изменений. Используется всеми хранилищами.
@MainActor
final class QuoteSubscriptions {
    typealias Stream = AsyncThrowingStream<[BookQuote], any Error>

    private struct Subscriber {
        let bookID: UUID
        let continuation: Stream.Continuation
    }

    private var subscribers: [UUID: Subscriber] = [:]

    /// `load` читает текущий список книги; вызывается сразу и после каждого `notify`.
    func makeStream(bookID: UUID, load: () throws -> [BookQuote]) -> Stream {
        let (stream, continuation) = Stream.makeStream(bufferingPolicy: .bufferingNewest(1))
        do {
            continuation.yield(try load())
        } catch {
            continuation.finish(throwing: error)
            return stream
        }
        let token = UUID()
        subscribers[token] = Subscriber(bookID: bookID, continuation: continuation)
        continuation.onTermination = { [weak self] _ in
            Task { @MainActor in
                self?.subscribers[token] = nil
            }
        }
        return stream
    }

    func notify(bookID: UUID, load: () throws -> [BookQuote]) {
        let affected = subscribers.filter { $0.value.bookID == bookID }
        guard !affected.isEmpty else { return }
        let result = Result { try load() }
        for (token, subscriber) in affected {
            switch result {
            case .success(let quotes):
                if case .terminated = subscriber.continuation.yield(quotes) {
                    subscribers[token] = nil
                }
            case .failure(let error):
                subscriber.continuation.finish(throwing: error)
                subscribers[token] = nil
            }
        }
    }
}
```

## Файл 3. `SwiftDataQuoteStore.swift`: работа через SwiftData

```swift
import Foundation
import SwiftData

/// Хранилище на SwiftData. Модель `Quote` не меняется.
@MainActor
final class SwiftDataQuoteStore: QuoteStore {
    private let context: ModelContext
    private let now: () -> Date
    private let subscriptions: QuoteSubscriptions

    init(container: ModelContainer, now: @escaping () -> Date = { .now }) {
        let context = ModelContext(container)
        context.autosaveEnabled = false
        self.context = context
        self.now = now
        self.subscriptions = QuoteSubscriptions()
    }

    func quotes(ofBook bookID: UUID) -> AsyncThrowingStream<[BookQuote], any Error> {
        subscriptions.makeStream(bookID: bookID) { try fetchQuotes(ofBook: bookID) }
    }

    @discardableResult
    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote {
        let cleanText = try BookQuote.normalizedText(text)
        let quote = Quote(id: UUID(), text: cleanText, bookID: bookID, createdAt: now())
        context.insert(quote)
        try saveOrRollback()
        subscriptions.notify(bookID: bookID) { try fetchQuotes(ofBook: bookID) }
        return BookQuote(quote)
    }

    func deleteQuote(id quoteID: UUID) async throws {
        guard let quote = try fetchQuote(id: quoteID) else { return }
        let bookID = quote.bookID
        context.delete(quote)
        try saveOrRollback()
        subscriptions.notify(bookID: bookID) { try fetchQuotes(ofBook: bookID) }
    }

    private func fetchQuotes(ofBook bookID: UUID) throws -> [BookQuote] {
        let descriptor = FetchDescriptor<Quote>(
            predicate: #Predicate { $0.bookID == bookID },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        return try context.fetch(descriptor).map(BookQuote.init)
    }

    private func fetchQuote(id quoteID: UUID) throws -> Quote? {
        var descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.id == quoteID })
        descriptor.fetchLimit = 1
        return try context.fetch(descriptor).first
    }

    /// Если сохранить не удалось, отменяет несохранённое, чтобы в памяти не осталось
    /// цитаты, которой нет на диске.
    private func saveOrRollback() throws {
        do {
            try context.save()
        } catch {
            context.rollback()
            throw error
        }
    }
}

private extension BookQuote {
