## Файл 4. `InMemoryQuoteStore.swift`: хранилище в памяти для превью и тестов

```swift
import Foundation

/// Хранит цитаты в памяти. Для превью SwiftUI и тестов, не для рабочего приложения.
@MainActor
final class InMemoryQuoteStore: QuoteStore {
    private var storage: [UUID: BookQuote]
    private let now: () -> Date
    private let subscriptions: QuoteSubscriptions

    init(quotes: [BookQuote] = [], now: @escaping () -> Date = { .now }) {
        self.storage = Dictionary(quotes.map { ($0.id, $0) }, uniquingKeysWith: { _, last in last })
        self.now = now
        self.subscriptions = QuoteSubscriptions()
    }

    func quotes(ofBook bookID: UUID) -> AsyncThrowingStream<[BookQuote], any Error> {
        subscriptions.makeStream(bookID: bookID) { snapshot(ofBook: bookID) }
    }

    @discardableResult
    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote {
        let quote = BookQuote(
            id: UUID(),
            bookID: bookID,
            text: try BookQuote.normalizedText(text),
            createdAt: now()
        )
        storage[quote.id] = quote
        subscriptions.notify(bookID: bookID) { snapshot(ofBook: bookID) }
        return quote
    }

    func deleteQuote(id quoteID: UUID) async throws {
        guard let quote = storage.removeValue(forKey: quoteID) else { return }
        subscriptions.notify(bookID: quote.bookID) { snapshot(ofBook: quote.bookID) }
    }

    private func snapshot(ofBook bookID: UUID) -> [BookQuote] {
        storage.values.filter { $0.bookID == bookID }.sorted(by: BookQuote.newestFirst)
    }
}
```

