            SwiftDataQuoteStore(container: container, now: { clock.tick() }),
        ]
    }

    private func firstSnapshot(_ store: any QuoteStore, bookID: UUID) async throws -> [BookQuote] {
        for try await quotes in store.quotes(ofBook: bookID) {
            return quotes
        }
        return []
    }

